const tokens = require("../../plugins/generated/native-tokens.json");

/** @type {import('@bacons/apple-targets/app.plugin').ConfigFunction} */
module.exports = (config) => ({
  type: "watch",
  name: "MunibTrackerWatch",
  bundleIdentifier: ".munibtrackerwatch",
  displayName: "Munib Tracker",
  deploymentTarget: "10.0",
  // Light canvas (not phone icon.png #152921) — watchOS circular mask on a black
  // home screen; App Review Guideline 4 rejects near-black full-bleed Watch icons.
  // Generated by `pnpm --filter app generate:brand-assets` from icon-512-watch-apple.png.
  icon: "../../assets/images/icon-watch-1024.png",
  colors: {
    // watchOS is always dark but resolves the asset's universal (light) entry, so both
    // use the dark-mode accent — the light #2E7D32 was unreadable on the black canvas.
    $accent: { light: tokens.defaultAccent.dark, dark: tokens.defaultAccent.dark },
  },
  frameworks: ["SwiftUI", "WatchConnectivity", "WidgetKit"],
  entitlements: {
    "com.apple.security.application-groups": [
      config.ios?.entitlements?.["com.apple.security.application-groups"]?.[0] ??
        "group.app.munibtracker.widgets",
    ],
  },
});
